import { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Wallet,
  CreditCard,
  Droplets,
  Star,
  Gift,
  QrCode,
  ArrowUpRight,
  ArrowDownRight,
  RefreshCw,
  Clock,
  ChevronDown,
  ChevronUp,
  Loader2,
  Plus,
  Ticket,
  TrendingUp,
  AlertCircle,
} from 'lucide-react';
import { useLanguage } from '@/lib/languageStore';
import { startWalletTopUpCheckout } from '@/lib/sumitCheckout';
import { Layout } from '@/components/Layout';
import { useLocation } from 'wouter';
import { useFirebaseAuth } from '@/auth/AuthProvider';
import { queryClient, apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';

interface WalletSummary {
  walletId: string;
  userId: string;
  cashWalletBalanceCents: number;
  egiftBalanceCents: number;
  washPackageCredits: number;
  loyaltyPointsBalance: number;
  promoBalanceCents: number;
  referralBalanceCents: number;
  pendingBalanceCents: number;
  lifetimeEarnedCents: number;
  lifetimeRedeemedCents: number;
  totalCreditsValueCents: number;
  loyaltyTier: string;
  tierPointsThisYear: number;
  unifiedVouchers?: {
    totalPlatformCreditRemainingCents: number;
    totalWashPackagesRemaining: number;
    activeVoucherCount: number;
  };
}

interface ActivityItem {
  id: string;
  type: 'wallet_credit' | 'voucher_ledger';
  event: string;
  description: string;
  amountCents: number | null;
  amountWashes: number | null;
  channel: string | null;
  platform: string | null;
  createdAt: string;
  referenceId: string | null;
}

const GOLD = '#D9B84C';

const formatCurrency = (cents: number) =>
  `₪${(cents / 100).toLocaleString('en-IL', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

// Canonical luxe labels — internal ids unchanged (no money-math change). Mirror of lib/loyalty.ts TIER_DISPLAY_LABELS.
const TIER_LABELS: Record<string, { en: string; he: string; emoji: string }> = {
  bronze: { en: 'Member', he: 'חבר', emoji: '🥉' },
  silver: { en: 'Silver', he: 'כסף', emoji: '🥈' },
  gold: { en: 'Gold', he: 'זהב', emoji: '🥇' },
  platinum: { en: 'Platinum', he: 'פלטינה', emoji: '💎' },
  diamond: { en: 'Diamond', he: 'יהלום', emoji: '💠' },
  emerald: { en: 'Emerald', he: 'אמרלד', emoji: '💚' },
  royal: { en: 'Black Reserve', he: 'Black Reserve', emoji: '👑' },
};

const TX_TYPE_ICONS: Record<string, { icon: typeof ArrowUpRight; color: string }> = {
  issue: { icon: ArrowUpRight, color: 'text-green-600' },
  redeem: { icon: ArrowDownRight, color: 'text-red-500' },
  refund: { icon: ArrowUpRight, color: 'text-[#B8932F]' },
  expire: { icon: Clock, color: 'text-gray-400' },
};

const CHANNEL_COLORS: Record<string, string> = {
  STATION: 'bg-[#D4AF37]',
  WEB: 'bg-[#D4AF37]',
  APP: 'bg-green-500',
};

function WalletSkeleton() {
  return (
    <Layout>
      <div className="min-h-screen bg-white py-6 px-4">
        <div className="max-w-lg mx-auto space-y-5">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-32 w-full rounded-2xl" />
          <div className="grid grid-cols-2 gap-3">
            <Skeleton className="h-28 rounded-xl" />
            <Skeleton className="h-28 rounded-xl" />
            <Skeleton className="h-28 rounded-xl" />
            <Skeleton className="h-28 rounded-xl" />
          </div>
          <Skeleton className="h-14 w-full rounded-xl" />
        </div>
      </div>
    </Layout>
  );
}

export default function MyWallet() {
  const { language } = useLanguage();
  const isHebrew = language === 'he';
  const [, setLocation] = useLocation();
  const { user } = useFirebaseAuth();
  const { toast } = useToast();
  const [showActivity, setShowActivity] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [showTopUp, setShowTopUp] = useState(false);
  const [nayaxTxId, setNayaxTxId] = useState('');
  const [topUpAmountIls, setTopUpAmountIls] = useState('');
  const [payByCardLoading, setPayByCardLoading] = useState(false);

  const { data: walletData, isLoading } = useQuery<{ success: boolean; wallet: WalletSummary }>({
    queryKey: ['/api/credit-wallet/summary'],
  });

  const { data: activityData, isLoading: activityLoading } = useQuery<{ success: boolean; activities: ActivityItem[]; total: number }>({
    queryKey: ['/api/credit-wallet/activity'],
    enabled: showActivity,
  });

  const { data: bookingStats } = useQuery<{ count: number }>({
    queryKey: ['/api/booking-requests/my-completed-count'],
    enabled: !!user,
  });

  const topUpMutation = useMutation({
    mutationFn: async (body: { amountCents: number; nayaxTxId?: string }) =>
      apiRequest('POST', '/api/credit-wallet/topup', body),
    onSuccess: () => {
      toast({
        title: isHebrew ? 'הארנק נטען בהצלחה!' : 'Wallet topped up!',
        description: isHebrew ? 'היתרה עודכנה' : 'Your balance has been updated',
      });
      queryClient.invalidateQueries({ queryKey: ['/api/credit-wallet/summary'] });
      queryClient.invalidateQueries({ queryKey: ['/api/credit-wallet/activity'] });
      setShowTopUp(false);
      setNayaxTxId('');
      setTopUpAmountIls('');
    },
    onError: (err: any) => {
      toast({
        variant: 'destructive',
        title: isHebrew ? 'שגיאה' : 'Error',
        description: err?.message || (isHebrew ? 'אירעה שגיאה' : 'An error occurred'),
      });
    },
  });

  const wallet = walletData?.wallet;
  const activities = activityData?.activities || [];

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await queryClient.invalidateQueries({ queryKey: ['/api/credit-wallet/summary'] });
    if (showActivity) {
      await queryClient.invalidateQueries({ queryKey: ['/api/credit-wallet/activity'] });
    }
    setTimeout(() => setIsRefreshing(false), 800);
  };

  // Nayax-station path: the user paid at a K9000 station and enters the
  // confirmation code; the server verifies (userId, nayaxTxId, amount) against
  // the recorded Nayax transaction before crediting. Requires a code.
  const handleTopUpSubmit = () => {
    const amountCents = Math.round(parseFloat(topUpAmountIls) * 100);
    if (!topUpAmountIls || isNaN(amountCents) || amountCents < 100) {
      toast({
        variant: 'destructive',
        title: isHebrew ? 'סכום לא תקין' : 'Invalid amount',
        description: isHebrew ? 'הסכום המינימלי הוא ₪1' : 'Minimum amount is ₪1',
      });
      return;
    }
    topUpMutation.mutate({ amountCents, nayaxTxId: nayaxTxId || undefined });
  };

  // Pay-by-card path: charge the customer FIRST via the SUMIT hosted page. The
  // wallet is credited ONLY by the verified SUMIT webhook flow (server-side),
  // never on this client request. No balance moves until payment is verified.
  const handlePayByCard = async () => {
    const amountIls = parseFloat(topUpAmountIls);
    if (!topUpAmountIls || isNaN(amountIls) || amountIls < 1) {
      toast({
        variant: 'destructive',
        title: isHebrew ? 'סכום לא תקין' : 'Invalid amount',
        description: isHebrew ? 'הסכום המינימלי הוא ₪1' : 'Minimum amount is ₪1',
      });
      return;
    }
    setPayByCardLoading(true);
    const result = await startWalletTopUpCheckout({ amountIls });
    if (!result.ok) {
      setPayByCardLoading(false);
      toast({
        variant: 'destructive',
        title: isHebrew ? 'שגיאה' : 'Error',
        description: result.error || (isHebrew ? 'התשלום אינו זמין כעת' : 'Payments are not available right now'),
      });
    }
    // On success the browser navigates to the SUMIT hosted page.
  };

  if (isLoading) return <WalletSkeleton />;

  const tier = wallet?.loyaltyTier || 'bronze';
  const tierInfo = TIER_LABELS[tier] || TIER_LABELS.bronze;
  const uv = wallet?.unifiedVouchers;

  return (
    <Layout>
      <div className="min-h-screen bg-white py-6 px-4">
        <div className="max-w-lg mx-auto">

          <div className="flex items-center justify-between mb-6 luxury-animate-fade-in">
            <div>
              <h1 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                <Wallet className="w-5 h-5 text-[#B8932F]" />
                {isHebrew ? 'הארנק שלי' : 'My Wallet'}
              </h1>
              <p className="text-sm text-gray-500 mt-0.5">
                {isHebrew ? '⁦PetWash™⁩ • קרדיטים ויתרות' : '⁦PetWash™⁩ • Credits & Balances'}
              </p>
            </div>
            <Button
              variant="ghost"
              size="icon"
              onClick={handleRefresh}
              disabled={isRefreshing}
              className="rounded-full"
            >
              <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
            </Button>
          </div>

          <Card className="luxury-glass-card luxury-shadow-lg mb-5 luxury-animate-slide-up overflow-hidden">
            <CardContent className="p-5 max-[375px]:p-3">
              <div className="flex items-center justify-between mb-3 max-[375px]:mb-2">
                <span className="text-sm max-[375px]:text-xs text-gray-500">
                  {isHebrew ? 'סך הקרדיטים' : 'Total Credits Value'}
                </span>
                <Badge className="bg-white border border-gray-200 text-gray-700 text-xs font-semibold">
                  {tierInfo.emoji} {isHebrew ? tierInfo.he : tierInfo.en}
                </Badge>
              </div>
              <div className="text-4xl max-[375px]:text-2xl font-bold text-gray-900 mb-1">
                {formatCurrency(wallet?.totalCreditsValueCents || 0)}
              </div>
              <p className="text-xs text-gray-400">
                {isHebrew ? `${wallet?.tierPointsThisYear?.toLocaleString() || 0} נקודות השנה` : `${wallet?.tierPointsThisYear?.toLocaleString() || 0} points this year`}
              </p>
            </CardContent>
          </Card>

          {/* T002: First booking conversion banner — show when funded with 0 completed bookings */}
          {(wallet?.totalCreditsValueCents ?? 0) > 0 && (bookingStats?.count ?? 1) === 0 && (
            <div
              className="rounded-2xl p-4 mb-4 luxury-animate-slide-up flex items-center justify-between gap-3"
              style={{ background: 'linear-gradient(135deg, #fdf8ee 0%, #fff9ef 100%)', border: `1.5px solid ${GOLD}44` }}
            >
              <div className="min-w-0">
                <p className="font-bold text-sm text-gray-900">
                  {isHebrew ? '🎉 הארנק מוכן — הזמן שירות ראשון!' : '🎉 Wallet ready — book your first service!'}
                </p>
                <p className="text-xs text-gray-500 mt-0.5">
                  {isHebrew ? 'השתמש ביתרה שלך לחוויה ראשונה' : 'Use your balance for a first-time experience'}
                </p>
              </div>
              <button
                onClick={() => setLocation('/marketplace')}
                className="flex-shrink-0 text-xs font-bold px-4 py-2 rounded-xl text-white"
                style={{ background: GOLD }}
              >
                {isHebrew ? 'הזמן עכשיו' : 'Book Now'}
              </button>
            </div>
          )}

          <div className="grid grid-cols-2 gap-3 max-[375px]:gap-2 mb-3 luxury-animate-slide-up">
            {/* Cash Wallet */}
            <Card className="luxury-glass-card col-span-2 border border-emerald-100">
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-lg bg-emerald-50 flex items-center justify-center">
                      <Wallet className="w-4 h-4 text-emerald-600" />
                    </div>
                    <span className="text-sm font-semibold text-gray-700">
                      {isHebrew ? 'ארנק מזומן' : 'Cash Wallet'}
                    </span>
                  </div>
                  <div className="text-right">
                    <div className="text-2xl font-bold text-gray-900">
                      {formatCurrency(wallet?.cashWalletBalanceCents || 0)}
                    </div>
                    <p className="text-[10px] text-gray-400">
                      {isHebrew ? 'יתרה זמינה' : 'Available balance'}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="luxury-glass-card">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-8 h-8 rounded-lg bg-[#D4AF37] flex items-center justify-center">
                    <CreditCard className="w-4 h-4 text-[#B8932F]" />
                  </div>
                  <span className="text-xs text-gray-500">
                    {isHebrew ? 'מתנה דיגיטלית' : 'E-Gift'}
                  </span>
                </div>
                <div className="text-xl font-bold text-gray-900">
                  {formatCurrency(wallet?.egiftBalanceCents || 0)}
                </div>
              </CardContent>
            </Card>

            <Card className="luxury-glass-card">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-8 h-8 rounded-lg bg-emerald-50 flex items-center justify-center">
                    <Droplets className="w-4 h-4 text-emerald-600" />
                  </div>
                  <span className="text-xs text-gray-500">
                    {isHebrew ? 'חבילות שטיפה' : 'Wash Packages'}
                  </span>
                </div>
                <div className="text-xl font-bold text-gray-900">
                  {wallet?.washPackageCredits || 0}
                  <span className="text-sm font-normal text-gray-400 ml-1">
                    {isHebrew ? 'שטיפות' : 'washes'}
                  </span>
                </div>
              </CardContent>
            </Card>

            <Card className="luxury-glass-card">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-8 h-8 rounded-lg bg-white flex items-center justify-center">
                    <Star className="w-4 h-4 text-amber-500" />
                  </div>
                  <span className="text-xs text-gray-500">
                    {isHebrew ? 'נקודות נאמנות' : 'Loyalty Points'}
                  </span>
                </div>
                <div className="text-xl font-bold text-gray-900">
                  {(wallet?.loyaltyPointsBalance || 0).toLocaleString()}
                  <span className="text-sm font-normal text-gray-400 ml-1">pts</span>
                </div>
                <p className="text-[10px] text-gray-400 mt-0.5">
                  ≈ {formatCurrency((wallet?.loyaltyPointsBalance || 0) * 10)}
                </p>
              </CardContent>
            </Card>

            <Card className="luxury-glass-card">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-8 h-8 rounded-lg bg-[#D4AF37] flex items-center justify-center">
                    <Gift className="w-4 h-4 text-[#B8932F]" />
                  </div>
                  <span className="text-xs text-gray-500">
                    {isHebrew ? 'קרדיט מבצע' : 'Promo Credits'}
                  </span>
                </div>
                <div className="text-xl font-bold text-gray-900">
                  {formatCurrency((wallet?.promoBalanceCents || 0) + (wallet?.referralBalanceCents || 0))}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Pending / Reserved Balance */}
          {(wallet?.pendingBalanceCents || 0) > 0 && (
            <Card className="mb-3 border border-amber-200 bg-amber-50 luxury-animate-slide-up">
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <AlertCircle className="w-4 h-4 text-amber-600" />
                    <span className="text-sm font-semibold text-amber-800">
                      {isHebrew ? 'יתרה מוקפאת' : 'Reserved (Pending)'}
                    </span>
                  </div>
                  <div className="text-right">
                    <div className="text-xl font-bold text-amber-800">
                      {formatCurrency(wallet?.pendingBalanceCents || 0)}
                    </div>
                  </div>
                </div>
                <p className="text-xs text-amber-600 mt-1">
                  {isHebrew
                    ? 'סכום זה מוקפא עבור הזמנות פעילות. הוא ישוחרר או יחויב לאחר אישור הספק.'
                    : 'This amount is reserved by active bookings. It will be released or charged after provider confirmation.'}
                </p>
              </CardContent>
            </Card>
          )}

          {/* Lifetime Stats */}
          {((wallet?.lifetimeEarnedCents || 0) > 0 || (wallet?.lifetimeRedeemedCents || 0) > 0) && (
            <Card className="mb-5 luxury-glass-card luxury-animate-slide-up">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-3">
                  <TrendingUp className="w-4 h-4 text-gray-500" />
                  <span className="text-sm font-semibold text-gray-700">
                    {isHebrew ? 'סטטיסטיקה לכל החיים' : 'Lifetime Stats'}
                  </span>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-xs text-gray-400 mb-0.5">{isHebrew ? 'סה״כ נצבר' : 'Total earned'}</p>
                    <p className="text-lg font-bold text-green-700">
                      {formatCurrency(wallet?.lifetimeEarnedCents || 0)}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-400 mb-0.5">{isHebrew ? 'סה״כ נוצל' : 'Total redeemed'}</p>
                    <p className="text-lg font-bold text-gray-700">
                      {formatCurrency(wallet?.lifetimeRedeemedCents || 0)}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {uv && uv.activeVoucherCount > 0 && (
            <Card className="luxury-glass-card mb-5 luxury-animate-slide-up border border-amber-100">
              <CardContent className="p-4">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <Ticket className="w-4 h-4 text-amber-600" />
                    <span className="text-sm font-semibold text-gray-800">
                      {isHebrew ? 'שוברים פעילים' : 'Active Vouchers'}
                    </span>
                  </div>
                  <Badge className="bg-amber-100 text-amber-700 border-0 text-xs font-bold">
                    {uv.activeVoucherCount}
                  </Badge>
                </div>
                <div className="space-y-1.5 mb-3">
                  {uv.totalPlatformCreditRemainingCents > 0 && (
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-500 flex items-center gap-1">
                        <CreditCard className="w-3.5 h-3.5 text-[#D4AF37]" />
                        {isHebrew ? 'קרדיט פלטפורמה' : 'Platform Credit'}
                      </span>
                      <span className="font-semibold text-gray-800">
                        {formatCurrency(uv.totalPlatformCreditRemainingCents)}
                      </span>
                    </div>
                  )}
                  {uv.totalWashPackagesRemaining > 0 && (
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-500 flex items-center gap-1">
                        <Droplets className="w-3.5 h-3.5 text-[#D4AF37]" />
                        {isHebrew ? 'חבילות שטיפה' : 'Wash Packages'}
                      </span>
                      <span className="font-semibold text-gray-800">
                        {uv.totalWashPackagesRemaining} {isHebrew ? 'שטיפות' : 'washes'}
                      </span>
                    </div>
                  )}
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setLocation('/vouchers')}
                  className="w-full text-amber-700 border-amber-200 hover:bg-amber-50 text-xs h-8"
                >
                  {isHebrew ? 'צפייה בכל השוברים' : 'View All Vouchers'}
                </Button>
              </CardContent>
            </Card>
          )}

          <div className="space-y-3 mb-6 luxury-animate-slide-up">
            <Button
              onClick={() => setLocation('/wallet/redeem')}
              className="w-full h-14 rounded-xl bg-[#B8932F] hover:bg-[#B8932F] text-white shadow-lg text-base font-semibold gap-3"
            >
              <QrCode className="w-5 h-5" />
              {isHebrew ? 'מימוש בתחנת K9000' : 'Redeem at K9000 Station'}
            </Button>

            <Button
              variant="outline"
              onClick={() => setShowTopUp(true)}
              className="w-full h-12 rounded-xl border-2 border-green-300 text-green-700 hover:bg-green-50 font-semibold gap-2"
            >
              <Plus className="w-4 h-4" />
              {isHebrew ? 'טעינת ארנק' : 'Top Up Wallet'}
            </Button>

            {/* T001: Send as Gift CTA */}
            <Button
              variant="outline"
              onClick={() => setLocation('/e-gift')}
              className="w-full h-12 rounded-xl font-semibold gap-2"
              style={{ borderColor: GOLD, color: GOLD }}
            >
              <Gift className="w-4 h-4" />
              {isHebrew ? 'שלח כמתנה' : 'Send as Gift'}
            </Button>

            <Button
              variant="outline"
              onClick={() => setShowActivity(!showActivity)}
              className="w-full h-12 rounded-xl border-2 border-gray-200 text-gray-700 font-semibold gap-2"
            >
              <Clock className="w-4 h-4" />
              {isHebrew ? 'היסטוריית פעולות' : 'Transaction History'}
              {showActivity ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
            </Button>
          </div>

          {showActivity && (
            <div className="luxury-animate-slide-up">
              <Card className="luxury-glass-card luxury-shadow-lg">
                <CardContent className="p-4">
                  <h3 className="text-sm font-semibold text-gray-700 mb-3">
                    {isHebrew ? 'פעולות אחרונות' : 'Recent Activity'}
                  </h3>
                  {activityLoading ? (
                    <div className="flex items-center justify-center py-8">
                      <Loader2 className="w-6 h-6 animate-spin text-gray-400" />
                    </div>
                  ) : activities.length === 0 ? (
                    <div className="text-center py-8 text-gray-400">
                      <Clock className="w-8 h-8 mx-auto mb-2 opacity-30" />
                      <p className="text-sm">{isHebrew ? 'אין פעולות עדיין' : 'No activity yet'}</p>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {activities.slice(0, 30).map((item) => {
                        const isPositive = ['issue', 'refund', 'ISSUED', 'LOAD'].includes(item.event);
                        const txTypeKey = item.event?.toLowerCase();
                        const txType = TX_TYPE_ICONS[txTypeKey] || (isPositive ? TX_TYPE_ICONS.issue : TX_TYPE_ICONS.redeem);
                        const TxIcon = txType.icon;
                        const channelKey = (item.channel || '').toUpperCase();
                        const channelDotColor = CHANNEL_COLORS[channelKey] || 'bg-gray-400';

                        return (
                          <div key={item.id} className="flex items-center justify-between py-2 border-b border-gray-100 last:border-0">
                            <div className="flex items-center gap-3">
                              <div className="w-8 h-8 rounded-lg bg-white flex items-center justify-center">
                                <TxIcon className={`w-4 h-4 ${txType.color}`} />
                              </div>
                              <div>
                                <div className="flex items-center gap-1.5">
                                  <p className="text-sm font-medium text-gray-900">
                                    {item.description || item.event}
                                  </p>
                                  {item.channel && (
                                    <span className={`inline-block w-2 h-2 rounded-full ${channelDotColor}`} title={item.channel} />
                                  )}
                                </div>
                                <p className="text-[11px] text-gray-400">
                                  {item.type === 'voucher_ledger' ? (isHebrew ? 'שובר' : 'Voucher') : (isHebrew ? 'ארנק' : 'Wallet')}
                                  {' • '}
                                  {new Date(item.createdAt).toLocaleDateString(isHebrew ? 'he-IL' : 'en-IL')}
                                </p>
                              </div>
                            </div>
                            <div className="text-right">
                              {item.amountCents != null && (
                                <span className={`text-sm font-semibold block ${isPositive ? 'text-green-600' : 'text-red-500'}`}>
                                  {isPositive ? '+' : '-'}{formatCurrency(Math.abs(item.amountCents))}
                                </span>
                              )}
                              {item.amountWashes != null && item.amountWashes !== 0 && (
                                <span className="text-xs text-gray-400 block">
                                  {item.amountWashes > 0 ? '+' : ''}{item.amountWashes} {isHebrew ? 'שטיפות' : 'washes'}
                                </span>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          )}

          <div className="mt-8 text-center text-xs text-gray-400 pb-4">
            <p>⁦PetWash™⁩ Wallet • {isHebrew ? 'מאובטח ומוצפן' : 'Secured & Encrypted'}</p>
          </div>
        </div>
      </div>

      <Dialog open={showTopUp} onOpenChange={setShowTopUp}>
        <DialogContent className="max-w-sm mx-auto">
          <DialogHeader>
            <DialogTitle className="text-center">
              {isHebrew ? 'טעינת ארנק' : 'Top Up Wallet'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            <div className="space-y-1.5">
              <Label htmlFor="topup-amount" className="text-sm font-medium text-gray-700">
                {isHebrew ? 'סכום לטעינה ₪' : 'Top-Up Amount ₪'}
              </Label>
              <Input
                id="topup-amount"
                type="number"
                min="1"
                step="0.01"
                value={topUpAmountIls}
                onChange={(e) => setTopUpAmountIls(e.target.value)}
                placeholder={isHebrew ? 'לדוגמה: 50' : 'e.g. 50'}
                className="h-11"
              />
            </div>

            {/* Primary path: pay by card. The customer is charged on SUMIT's
                hosted page FIRST; the wallet credits only after the payment is
                verified server-side. */}
            <Button
              onClick={handlePayByCard}
              disabled={payByCardLoading}
              className="w-full h-12 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-xl gap-2"
            >
              {payByCardLoading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <CreditCard className="w-4 h-4" />
              )}
              {isHebrew ? 'שלם בכרטיס אשראי' : 'Pay by Card'}
            </Button>

            {/* Secondary path: confirm a top-up already paid at a K9000 station.
                The server verifies the Nayax confirmation code before crediting. */}
            <div className="pt-2 border-t border-gray-100">
              <div className="bg-[#D4AF37] rounded-xl p-3 text-xs text-[#B8932F] leading-relaxed mb-3">
                <p className="font-semibold mb-1">{isHebrew ? 'שילמת בתחנת K9000?' : 'Already paid at a K9000 station?'}</p>
                <p>{isHebrew
                  ? 'הזן את קוד האישור של Nayax כדי לזכות את הארנק'
                  : 'Enter the Nayax confirmation code to credit your wallet'
                }</p>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="nayax-tx-id" className="text-sm font-medium text-gray-700">
                  {isHebrew ? 'קוד אישור Nayax' : 'Nayax Confirmation Code'}
                </Label>
                <Input
                  id="nayax-tx-id"
                  value={nayaxTxId}
                  onChange={(e) => setNayaxTxId(e.target.value)}
                  placeholder={isHebrew ? 'הזן קוד אישור' : 'Enter confirmation code'}
                  className="h-11"
                />
              </div>
              <Button
                onClick={handleTopUpSubmit}
                disabled={topUpMutation.isPending || !nayaxTxId}
                variant="outline"
                className="w-full h-11 mt-3 font-semibold rounded-xl gap-2"
              >
                {topUpMutation.isPending ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Plus className="w-4 h-4" />
                )}
                {isHebrew ? 'אשר טעינת תחנה' : 'Confirm Station Top-Up'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </Layout>
  );
}
